import{_ as t,o,c as e,a2 as r}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"篇729｜挂机养老批判·总论——网文天帝仙帝的共同病","description":"","frontmatter":{"title":"篇729｜挂机养老批判·总论——网文天帝仙帝的共同病","no":729,"module":4,"tags":["挂机养老","总论","天帝仙帝","共同病","主角唯一性依赖度"],"related":["0004-反掠夺主义核心论纲","0017-位面至高强者标准","0090-术语词典"]},"headers":[],"relativePath":"zh/0729_模块4-挂机养老批判总论.md","filePath":"zh/0729_模块4-挂机养老批判总论.md"}'),l={name:"zh/0729_模块4-挂机养老批判总论.md"};function i(u,a,h,n,q,s){return o(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="篇729-挂机养老批判·总论——网文天帝仙帝的共同病" tabindex="-1">篇729｜挂机养老批判·总论——网文天帝仙帝的共同病 <a class="header-anchor" href="#篇729-挂机养老批判·总论——网文天帝仙帝的共同病" aria-label="Permalink to &quot;篇729｜挂机养老批判·总论——网文天帝仙帝的共同病&quot;">​</a></h1><blockquote><p>所属模块：模块四·超脱正统定义库｜对标地基：文档04、17、90</p></blockquote><h2 id="引言-一个共同的结局-一种共同的病" tabindex="-1">引言：一个共同的结局，一种共同的病 <a class="header-anchor" href="#引言-一个共同的结局-一种共同的病" aria-label="Permalink to &quot;引言：一个共同的结局，一种共同的病&quot;">​</a></h2><p>模块四的最后五篇，要把批判落到具体IP上。但在批判叶凡、石昊、唐三、悟空之前，必须先把&quot;挂机养老&quot;这个病的共性讲清楚——为什么诸天网文里的天帝、仙帝、宇宙主宰，最后都得了同一种病？这不是某一个作者的问题，这是整个网文范式的结构性问题。</p><p>六大顶层公理在这一篇同时作为批判的尺子：反掠夺主义公理指出这些&quot;天帝仙帝&quot;的力量来路普遍不干净；万族共和公理质问他们凭什么垄断最高境界；集体升维公理指出他们不抬万族；因果自律公理指出他们的跨位面操作从不报备；法则优先公理指出他们的体系普遍吃书烂尾。</p><p>众生全员无限均等法则：锚点共生文明内，所有生灵自带基础无限之力；佛系/懒狗保有保底基础无限，不会被时代淘汰；卷王、少年至尊可叠加更多更高层级的无限。无限本源人人自带，掠夺自然失去意义。</p><h2 id="一、共同病的四个症状" tabindex="-1">一、共同病的四个症状 <a class="header-anchor" href="#一、共同病的四个症状" aria-label="Permalink to &quot;一、共同病的四个症状&quot;">​</a></h2><p>拆解遮天、完美世界、斗罗、龙珠这四大IP的结局，&quot;天帝仙帝病&quot;有四个共同症状：</p><h3 id="_1-1-终点即终点" tabindex="-1">1.1 终点即终点 <a class="header-anchor" href="#_1-1-终点即终点" aria-label="Permalink to &quot;1.1 终点即终点&quot;">​</a></h3><p>主角登顶之后，故事结束。他没有下一步，他不需要下一步。他的&quot;超脱&quot;是一个句号，不是一个逗号。</p><h3 id="_1-2-万族留在原地" tabindex="-1">1.2 万族留在原地 <a class="header-anchor" href="#_1-2-万族留在原地" aria-label="Permalink to &quot;1.2 万族留在原地&quot;">​</a></h3><p>主角飞升之后，身后的文明继续运转，但不再因为他而进步。他是文明的最高点，也是文明的天花板——后辈仰望即可，不必追上。</p><h3 id="_1-3-知识私人化" tabindex="-1">1.3 知识私人化 <a class="header-anchor" href="#_1-3-知识私人化" aria-label="Permalink to &quot;1.3 知识私人化&quot;">​</a></h3><p>主角的功法、经验、法则理解，要么只传血脉门徒，要么随他飞升消失。没有公开，没有无私道。</p><h3 id="_1-4-孤独的无敌" tabindex="-1">1.4 孤独的无敌 <a class="header-anchor" href="#_1-4-孤独的无敌" aria-label="Permalink to &quot;1.4 孤独的无敌&quot;">​</a></h3><p>主角最终状态是&quot;无敌、长生、寂寞&quot;。他不是与万族共生，他是站在万族之上。这种孤独被浪漫化，被读者当成强者的勋章。</p><p>四个症状合起来，就是&quot;挂机养老&quot;——<strong>他已经在宇宙的最高处挂机，不产生任何文明增量。</strong></p><h2 id="二、为什么这个病是结构性的" tabindex="-1">二、为什么这个病是结构性的 <a class="header-anchor" href="#二、为什么这个病是结构性的" aria-label="Permalink to &quot;二、为什么这个病是结构性的&quot;">​</a></h2><p>这个病不是某一个作者写崩了，它是网文范式的必然产物：</p><ul><li><strong>爽文逻辑</strong>：读者要的是&quot;主角变强&quot;的爽感，不是&quot;主角干活&quot;的劳动感。作者写到主角无敌，故事的爽点就到头了</li><li><strong>主角唯一性</strong>：整个文明围绕主角转，主角一停，整个故事就停。主角唯一性依赖度评级普遍在&quot;中&quot;到&quot;极高&quot;</li><li><strong>无岗位概念</strong>：旧网文没有&quot;超脱者岗位&quot;这个设定，强者登顶之后没事可干，只能挂机</li><li><strong>无万族视角</strong>：故事从主角视角讲，万族只是背景板。作者没有动力描写&quot;主角登顶后万族怎么了&quot;</li></ul><p>四个结构性原因合起来，&quot;挂机养老&quot;不是bug，是feature——它是这套范式的必然结局。</p><h2 id="三、挂机养老的三层危害" tabindex="-1">三、挂机养老的三层危害 <a class="header-anchor" href="#三、挂机养老的三层危害" aria-label="Permalink to &quot;三、挂机养老的三层危害&quot;">​</a></h2><p>挂机养老看起来无害——主角都无敌了，让他歇歇怎么了？实际上它有三层危害：</p><h3 id="_3-1-文明增量的浪费" tabindex="-1">3.1 文明增量的浪费 <a class="header-anchor" href="#_3-1-文明增量的浪费" aria-label="Permalink to &quot;3.1 文明增量的浪费&quot;">​</a></h3><p>主角毕生修炼所得的全部算力、全部法则理解、全部文明影响，在他登顶那一刻停止产出。这是宇宙级能级浪费。</p><h3 id="_3-2-后辈的天花板" tabindex="-1">3.2 后辈的天花板 <a class="header-anchor" href="#_3-2-后辈的天花板" aria-label="Permalink to &quot;3.2 后辈的天花板&quot;">​</a></h3><p>主角太强、太无敌、太孤独，后辈不敢追、追不上、不必追。文明的进化速度被主角个人锁死。</p><h3 id="_3-3-读者价值观的污染" tabindex="-1">3.3 读者价值观的污染 <a class="header-anchor" href="#_3-3-读者价值观的污染" aria-label="Permalink to &quot;3.3 读者价值观的污染&quot;">​</a></h3><p>读者看完这种结局，会形成一种潜意识：<strong>修炼就是为了有一天可以不干活。</strong> 这种价值观渗透到现实，就是&quot;躺平即正义&quot;的文化根源之一。衡元宙文库的模块四，从法则层面反对这种价值观。</p><h2 id="四、衡元宙的替代方案" tabindex="-1">四、衡元宙的替代方案 <a class="header-anchor" href="#四、衡元宙的替代方案" aria-label="Permalink to &quot;四、衡元宙的替代方案&quot;">​</a></h2><p>衡元宙给&quot;天帝仙帝病&quot;的替代方案，就是前28篇讲过的一切：</p><ul><li>把&quot;终点&quot;改成&quot;岗位&quot;——衡锚超多元境是永久岗位境</li><li>把&quot;万族留在原地&quot;改成&quot;抬着万族走&quot;——集体升维公理</li><li>把&quot;知识私人化&quot;改成&quot;无私道公共库&quot;——反掠夺主义公理</li><li>把&quot;孤独的无敌&quot;改成&quot;九岗位共生&quot;——万族共和公理</li></ul><p>后四篇（730-733），将用这套替代方案，逐一量过叶凡、石昊、唐三、悟空。</p><h2 id="五、五大核心落点" tabindex="-1">五、五大核心落点 <a class="header-anchor" href="#五、五大核心落点" aria-label="Permalink to &quot;五、五大核心落点&quot;">​</a></h2><ul><li><strong>反能级浪费</strong>：挂机养老是文明级能级浪费，衡元宙用永动建设把它根绝</li><li><strong>反掠夺</strong>：挂机者的力量来路普遍不干净，旧网文不审计，衡元宙来路审计从根上切断</li><li><strong>唐罗上限对比</strong>：唐罗、古尘沙是主角唯一性依赖度&quot;极高&quot;的代表，挂机养老是这种依赖度的必然结局</li><li><strong>万族全覆盖</strong>：挂机者身后的99%族群被遗忘，衡元宙把这99%写进公理</li><li><strong>超多元全开放</strong>：挂机者的功法随他消失，衡元宙用无私道让知识永远流动</li><li><strong>全员无限均等</strong>：众生全员无限均等法则——锚点共生文明内人人自带基础无限之力，佛系懒狗保有保底基础无限、不被时代淘汰，卷王少年至尊可叠加更高层级无限；无限本源人人自带，掠夺自然失去意义</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>天帝仙帝病不是个别作者的问题，是整个网文范式的结构性问题。它的症状是终点即终点、万族留原地、知识私人化、孤独的无敌。衡元宙文库要做的，是从法则层面告诉一切修炼者：<strong>这不是强者的浪漫，这是文明的悲剧。</strong></p><p>理解了这个病的结构性，就理解了为什么后四篇的批判不是针对某一个角色——叶凡、石昊、唐三、悟空都是好角色，他们的悲剧是范式强加给他们的。衡元宙要做的不是否定这些角色，而是给他们（以及他们身后的亿万读者）一个新的选项：<strong>变强之后，不必挂机；登顶之后，不必孤独；无敌之后，不必无的。</strong> 后四篇，逐个看。</p><p>说到底，本篇所述的挂机养老批判总论并非孤例——其因果与能级留痕全程纳入阿赖耶网络备案、可溯可校。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>关联文档：<a href="./0004-反掠夺主义核心论纲.html">0004-反掠夺主义核心论纲</a> · <a href="./0017-位面至高强者标准.html">0017-位面至高强者标准</a> · <a href="./0090-术语词典.html">0090-术语词典</a> · <a href="./703-超脱不是躺平.html">703-超脱不是躺平</a></li></ul>',41)])])}const _=t(l,[["render",i]]);export{p as __pageData,_ as default};
